      }

      const windCompX = windFast.x + 0.18 * gustX;
      const windCompZ = windFast.z + 0.18 * gustZ;

      let ax = kpX * (tx - p.x) + kdX * (vxDes - v.x) + kDrag * v.x - windCompX;
      let az = kpZ * (tz - p.z) + kdZ * (vzDes - v.z) + intZ + kDrag * v.z - windCompZ;

      // In 'align' phase, strictly prevent crossing the gate plane x = g.x
      if (obs.gateIndex < 3 && phase === 'align') {
        const gx = obs.nextGate.centre.x;
        const marginX = gx - 0.11 - p.x;
        const vxSafe = clamp(2.2 * marginX, -0.8, 1.4);
        if (v.x > vxSafe) {
          ax = Math.min(ax, -7.5 * (v.x - vxSafe) - windCompX);
