      if (obs.gateIndex === 3 && p.y < 0.22) {
        maxTilt = p.y < 0.12 ? 0.13 : 0.22;
      }
      let desPitch = clamp(Math.atan2(accBodyX, totalAy), -maxTilt, maxTilt);
      let desRoll = clamp(-Math.atan2(accBodyZ * Math.cos(desPitch), totalAy), -maxTilt, maxTilt);

