const failures = [];
for (let s = 1; s <= N; s++) {
  const res = runFast(s);
  if (res.success) passed++;
  else failures.push(res);
}
console.log(`Passed: ${passed}/${N} (${(100*passed/N).toFixed(1)}%)`);
const reasons = {};
for (const f of failures) {
  const key = f.reason.split(" (")[0];
  reasons[key] = (reasons[key] || 0) + 1;
}
console.log("Failure breakdown:", reasons);
for (const f of failures.slice(0, 20)) {
  console.log(`  seed ${f.seed}: ${f.reason} | gates=${f.gatesPassed} (${f.gateTimes.join(",")}) | t=${f.t}s | pos=(${f.pos.x.toFixed(2)},${f.pos.y.toFixed(2)},${f.pos.z.toFixed(2)}) | padErr=${f.landingError}`);
}
